// frappe-nix:managed — generated by frappe-nix (`frappe-init --sync`); do not edit.
// Registers this app's Vite bundles in the bench's sites/assets/assets.json,
// so `bundled_asset("<name>.bundle.js")` and `app_include_js` find them on
// any bench. The `build` script ends with `node scripts/vite-register.mjs`:
// frappe's esbuild writes assets.json, then runs each app's `yarn build`, so
// these keys land after its own. Outside a bench it does nothing.
// See https://github.com/Avunu/frappe-nix/tree/main/docs/app-standards/assets.md
import fs from "node:fs";
import path from "node:path";
import process from "node:process";

// vite-register:begin
// A bundle Vite emitted: <name>.bundle.<hash>.<js|css>.
const BUNDLE = /^(?<name>[^/]+)\.bundle\.[A-Za-z0-9_-]{6,}\.(?<ext>js|css)$/;
// The key frappe looks a stylesheet up by in a right-to-left session.
const RTL_KEY = /^rtl_/;
const isRtlDir = (dir) => dir.endsWith("-rtl");

const isDir = (dir) => {
	try {
		return fs.statSync(dir).isDirectory();
	} catch {
		return false;
	}
};

const filesUnder = (dir) => {
	const out = [];
	for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
		const full = path.join(dir, entry.name);
		if (entry.isDirectory() && entry.name !== "node_modules") {
			out.push(...filesUnder(full));
		} else if (entry.isFile()) {
			out.push(full);
		}
	}
	return out.sort();
};

// manifest*.json and .vite/manifest*.json anywhere under public/dist.
const isManifest = (file) => /^manifest.*\.json$/.test(path.basename(file));
const manifestsUnder = (dist) => filesUnder(dist).filter(isManifest);

// A manifest's paths are relative to the outDir it was written for.
const outDirOf = (manifest) => {
	const dir = path.dirname(manifest);
	return path.basename(dir) === ".vite" ? path.dirname(dir) : dir;
};

const readManifest = (file, log) => {
	try {
		const doc = JSON.parse(fs.readFileSync(file, "utf8"));
		return doc && typeof doc === "object" ? doc : {};
	} catch (error) {
		log(`vite-register: skipping ${file}: ${error.message}`);
		return {};
	}
};

const mtimeOf = (file) => {
	try {
		return fs.statSync(file).mtimeMs;
	} catch {
		return null;
	}
};

// The keys an app's Vite manifests ask for, in a stable order. When two
// entries name the same key (a Vite 4 manifest.json left beside Vite 5's
// .vite/manifest.json, or an old outDir under public/dist), the newer file
// wins, whatever order the manifests are read in.
const bundleKeys = ({ appDir, app, log }) => {
	const dist = path.join(appDir, app, "public", "dist");
	const found = {};
	if (!isDir(dist)) {
		return {};
	}
	for (const manifest of manifestsUnder(dist)) {
		const outDir = outDirOf(manifest);
		const chunks = Object.entries(readManifest(manifest, log));
		for (const [id, chunk] of chunks) {
			// `cssCodeSplit: false` emits the build's one stylesheet as its
			// own record, "style.css", which no entry lists in its `css`.
			const sheet = id === "style.css";
			if (!chunk || (chunk.isEntry !== true && !sheet)) {
				continue;
			}
			const files = [chunk.file, ...(chunk.css || [])];
			for (const file of files) {
				if (typeof file !== "string") {
					continue;
				}
				const rel = path.relative(dist, path.join(outDir, file));
				const match = BUNDLE.exec(path.basename(rel));
				if (!match || rel.startsWith("..")) {
					continue;
				}
				// A manifest outlives its files: public/dist survives between
				// builds, and frappe's build cleanup deletes an old bundle but
				// never the manifest that named it.
				if (!fs.existsSync(path.join(dist, rel))) {
					log(`vite-register: ${app}: skipping ${rel}: not on disk`);
					continue;
				}
				const { name, ext } = match.groups;
				// A stylesheet under a *-rtl/ directory (frappe's own css-rtl/)
				// is the right-to-left build of <name>; any other file there is
				// a by-product of that build, not a second copy of the entry.
				const rtl = path.dirname(rel).split(path.sep).some(isRtlDir);
				if (rtl && ext !== "css") {
					continue;
				}
				const key = `${rtl ? "rtl_" : ""}${name}.bundle.${ext}`;
				const mtime = mtimeOf(path.join(dist, rel));
				const seen = found[key];
				if (seen && seen.rel !== rel && seen.mtime > mtime) {
					log(`vite-register: ${app}: skipping ${rel}: ${seen.rel} is newer`);
					continue;
				}
				if (seen && seen.rel !== rel) {
					log(`vite-register: ${app}: skipping ${seen.rel}: ${rel} is newer`);
				}
				found[key] = { rel, mtime };
			}
		}
	}
	const keys = {};
	for (const [key, { rel }] of Object.entries(found)) {
		const url = rel.split(path.sep).join("/");
		keys[key] = `/assets/${app}/dist/${url}`;
	}
	// frappe asks for rtl_<name>.bundle.css in an ar, he, fa or ps session.
	// Without a right-to-left build, the left-to-right stylesheet stands in:
	// the layout is not mirrored, but the page is styled, not a 404.
	for (const key of Object.keys(keys)) {
		const twin = `rtl_${key}`;
		if (key.endsWith(".bundle.css") && !RTL_KEY.test(key) && !keys[twin]) {
			keys[twin] = keys[key];
		}
	}
	return keys;
};

// frappe reads assets-rtl.json over assets.json and writes each rtl_ key to
// it alone, so a key there wins: an rtl_ key belongs in that file.
const assetsFileOf = (key) => {
	return RTL_KEY.test(key) ? "assets-rtl.json" : "assets.json";
};

const readJson = (file) => {
	if (!fs.existsSync(file)) {
		return {};
	}
	return JSON.parse(fs.readFileSync(file, "utf8"));
};

// frappe's own format: four spaces, no final newline.
const writeJson = (file, value) => {
	const tmp = `${file}.${process.pid}.tmp`;
	fs.writeFileSync(tmp, JSON.stringify(value, null, 4));
	fs.renameSync(tmp, file);
};

const sameFile = (a, b) => {
	try {
		const [x, y] = [fs.statSync(a), fs.statSync(b)];
		return x.ino === y.ino && x.dev === y.dev;
	} catch {
		return false;
	}
};

// Copy src into dest, file by file. A file that is a hard link of its
// source is left alone: copying onto it would truncate both.
const copyTree = (src, dest) => {
	for (const file of filesUnder(src)) {
		const target = path.join(dest, path.relative(src, file));
		if (sameFile(file, target)) {
			continue;
		}
		fs.mkdirSync(path.dirname(target), { recursive: true });
		fs.copyFileSync(file, target);
	}
};

// Whether a Vite build with `build.manifest` on wrote dir: it holds a .vite/
// directory (Vite 5) or a manifest*.json at its top (Vite 4).
const hasManifest = (dir) => {
	if (isDir(path.join(dir, ".vite"))) {
		return true;
	}
	return fs.readdirSync(dir).some(isManifest);
};

// public/dist, and each other directory under public/ that a Vite build wrote
// (a second SPA's outDir, such as public/portal/).
const viteOutDirs = (publicDir) => {
	const out = ["dist"];
	for (const entry of fs.readdirSync(publicDir, { withFileTypes: true })) {
		const dir = path.join(publicDir, entry.name);
		if (entry.isDirectory() && entry.name !== "dist" && hasManifest(dir)) {
			out.push(entry.name);
		}
	}
	return out.filter((name) => isDir(path.join(publicDir, name)));
};

// When sites/assets/<app> is a real directory rather than the link to the
// app's public/ (`bench build --hard-link`, or an image that copied public/
// before the app's build ran), the build's outputs are copied into it.
const copyOutputs = ({ appDir, app, sitesDir }) => {
	const target = path.join(sitesDir, "assets", app);
	let stat;
	try {
		stat = fs.lstatSync(target);
	} catch {
		return [];
	}
	if (stat.isSymbolicLink() || !stat.isDirectory()) {
		return [];
	}
	const publicDir = path.join(appDir, app, "public");
	if (!isDir(publicDir)) {
		return [];
	}
	const dirs = viteOutDirs(publicDir);
	for (const name of dirs) {
		copyTree(path.join(publicDir, name), path.join(target, name));
	}
	return dirs;
};

// The file an assets.json value names, under sites/assets/.
const servedFile = (sitesDir, url) => {
	if (typeof url !== "string" || !url.startsWith("/assets/")) {
		return null;
	}
	return path.join(sitesDir, url);
};

// Whether the file a key names now is newer than the Vite bundle: esbuild
// built that name after Vite last did, so the Vite file is stale.
const keptNewer = ({ appDir, app, sitesDir, current, value }) => {
	const now = servedFile(sitesDir, current);
	const prefix = `/assets/${app}/dist/`;
	const dist = path.join(appDir, app, "public", "dist");
	const vite = path.join(dist, value.slice(prefix.length));
	const [a, b] = [now && mtimeOf(now), mtimeOf(vite)];
	return a !== null && b !== null && a > b;
};

// Merge keys into one of sites/assets/assets.json and assets-rtl.json.
const mergeInto = ({ appDir, app, sitesDir, log, name, keys, ltr }) => {
	const file = path.join(sitesDir, "assets", name);
	const changed = [];
	if (Object.keys(keys).length === 0) {
		return changed;
	}
	const assets = readJson(file);
	for (const [key, value] of Object.entries(keys)) {
		const current = assets[key];
		if (current === value) {
			continue;
		}
		if (keptNewer({ appDir, app, sitesDir, current, value })) {
			log(`vite-register: ${app}: ${key} kept: ${value} is older`);
			continue;
		}
		assets[key] = value;
		changed.push(key);
		const how = value === ltr[key] ? "vite, no rtl build" : "vite";
		log(`vite-register: ${app}: ${key} -> ${value} (${how})`);
	}
	if (changed.length > 0) {
		fs.mkdirSync(path.dirname(file), { recursive: true });
		writeJson(file, assets);
	}
	return changed;
};

const register = ({ appDir, app, sitesDir, log = console.log }) => {
	const keys = bundleKeys({ appDir, app, log });
	const byFile = { "assets.json": {}, "assets-rtl.json": {} };
	// The stylesheet each rtl_ key would name without a right-to-left build.
	const ltr = {};
	for (const [key, value] of Object.entries(keys)) {
		byFile[assetsFileOf(key)][key] = value;
		if (RTL_KEY.test(key)) {
			ltr[key] = keys[key.replace(RTL_KEY, "")];
		}
	}
	const changed = [];
	for (const [name, part] of Object.entries(byFile)) {
		const args = { appDir, app, sitesDir, log, name, keys: part, ltr };
		changed.push(...mergeInto(args));
	}
	const copied = copyOutputs({ appDir, app, sitesDir });
	return { keys, changed, copied };
};

const realpath = (dir) => {
	try {
		return fs.realpathSync(dir);
	} catch {
		return null;
	}
};

// The bench's sites/ for a build running in <bench>/apps/<app>: the first of
// $FRAPPE_BENCH_ROOT/sites, the logical ../../sites (apps/<app> may be a
// link) and the physical one that holds apps.txt; null outside a bench.
const findSites = ({ env, cwd }) => {
	const candidates = [];
	if (env.FRAPPE_BENCH_ROOT) {
		candidates.push(path.join(env.FRAPPE_BENCH_ROOT, "sites"));
	}
	candidates.push(path.resolve(env.PWD || cwd, "../../sites"));
	candidates.push(path.join(realpath(cwd) || cwd, "../../sites"));
	const hasApps = (dir) => fs.existsSync(path.join(dir, "apps.txt"));
	return candidates.find(hasApps) || null;
};

// The Frappe app a repository root holds: the directory beside it with a
// hooks.py and a modules.txt (one per app, by frappe's layout).
const appOf = (appDir) => {
	const has = (e, file) => fs.existsSync(path.join(appDir, e.name, file));
	const found = [];
	for (const e of fs.readdirSync(appDir, { withFileTypes: true })) {
		if (e.isDirectory() && has(e, "hooks.py") && has(e, "modules.txt")) {
			found.push(e.name);
		}
	}
	return found.length === 1 ? found[0] : null;
};
// vite-register:end

const appDir = process.cwd();
const sitesDir = findSites({ env: process.env, cwd: appDir });
const app = appOf(appDir);
if (sitesDir === null) {
	console.log("vite-register: no bench found; skipped");
} else if (app === null) {
	console.error(`vite-register: no Frappe app package in ${appDir}`);
	process.exitCode = 1;
} else {
	// Like the preload's pass, a failure here never fails the app's build.
	try {
		register({ appDir, app, sitesDir });
	} catch (error) {
		const why = `${error.message}; its Vite bundles are not registered`;
		console.error(`vite-register: ${app}: ${why}`);
	}
}
